  --kilt-color-card-hairline: light-dark(color-mix(in oklab, #1c1c1c 8%, transparent), var(--kilt-color-border-1));
  --kilt-color-card-hover: light-dark(var(--kilt-color-panel), color-mix(in oklab, white 10%, var(--kilt-color-background)));
  --kilt-color-chart-other: light-dark(var(--kilt-color-muted-foreground-3), #555354);
  --kilt-color-chrome: light-dark(color-mix(in oklab, var(--kilt-color-background) 35%, oklch(94.31% 0.0006 286.15)), color-mix(in oklab, var(--kilt-color-background) 50%, oklch(14.66% 0.0015 286.15)));
  --kilt-color-composer-ground: light-dark(color-mix(in oklab, var(--kilt-color-card) 95%, var(--kilt-color-foreground)), #1e1e20);
  --kilt-color-destructive-soft: light-dark(color-mix(in oklch, var(--kilt-color-destructive) 18%, transparent), color-mix(in oklch, var(--kilt-color-destructive) 22%, transparent));
  --kilt-color-destructive-soft-hover: light-dark(color-mix( in oklch, var(--kilt-color-destructive) 24%, transparent ), color-mix( in oklch, var(--kilt-color-destructive) 28%, transparent ));
  --kilt-color-diff-add-emphasis: light-dark(color-mix(in oklch, var(--kilt-color-diff-add) 20%, transparent), color-mix(in oklch, var(--kilt-color-diff-add) 32%, transparent));
  --kilt-color-diff-del-emphasis: light-dark(color-mix(in oklch, var(--kilt-color-diff-del) 20%, transparent), color-mix(in oklch, var(--kilt-color-diff-del) 32%, transparent));
  --kilt-color-foreground: light-dark(#2d2d2b, #f9f9f7);
  --kilt-color-icon-muted: light-dark(color-mix(in oklch, var(--kilt-color-foreground) 42%, var(--kilt-color-background)), color-mix(in oklch, var(--kilt-color-foreground) 40%, var(--kilt-color-background)));
  --kilt-color-input: light-dark(var(--kilt-color-card), var(--kilt-color-card));
  --kilt-color-inverse: light-dark(var(--kilt-color-foreground), var(--kilt-color-foreground));
  --kilt-color-inverse-hover: light-dark(color-mix(in oklch, var(--kilt-color-foreground) 88%, var(--kilt-color-background)), color-mix(in oklch, var(--kilt-color-foreground) 88%, var(--kilt-color-background)));
  --kilt-color-inverse-text: light-dark(var(--kilt-color-background), var(--kilt-color-background));
  --kilt-color-muted: light-dark(color-mix(in oklab, black 3.5%, var(--kilt-color-background)), color-mix(in oklab, white 21.5%, var(--kilt-color-background)));
  --kilt-color-muted-foreground-1: light-dark(color-mix(in oklch, var(--kilt-color-foreground) 62%, var(--kilt-color-background)), color-mix(in oklch, var(--kilt-color-foreground) 68%, var(--kilt-color-background)));
  --kilt-color-muted-foreground-2: light-dark(color-mix(in oklch, var(--kilt-color-foreground) 48%, var(--kilt-color-background)), color-mix(in oklch, var(--kilt-color-foreground) 52%, var(--kilt-color-background)));
  --kilt-color-muted-foreground-3: light-dark(color-mix(in oklch, var(--kilt-color-foreground) 36%, var(--kilt-color-background)), color-mix(in oklch, var(--kilt-color-foreground) 38%, var(--kilt-color-background)));
  --kilt-color-panel: light-dark(color-mix(in oklab, white 66%, var(--kilt-color-background)), color-mix(in oklab, white 5%, var(--kilt-color-background)));
  --kilt-color-popover: light-dark(var(--kilt-color-card), color-mix(in oklab, white 11%, var(--kilt-color-background)));
  --kilt-color-primary: light-dark(#c65b3a, #e07a5f);
  --kilt-color-primary-foreground: light-dark(#fff, #fff);
  --kilt-color-primary-ink: light-dark(var(--kilt-color-primary), var(--kilt-color-primary));
  --kilt-color-primary-soft: light-dark(color-mix(in oklch, var(--kilt-color-primary) 8%, transparent), color-mix(in oklch, var(--kilt-color-primary) 20%, transparent));
  --kilt-color-primary-soft-hover: light-dark(color-mix(in oklch, var(--kilt-color-primary) 12%, transparent), color-mix(in oklch, var(--kilt-color-primary) 24%, transparent));
  --kilt-color-ring: light-dark(color-mix(in oklch, var(--kilt-color-primary) 92%, black), var(--kilt-color-primary));
  --kilt-color-segmented-foreground: light-dark(var(--kilt-color-muted-foreground-1), color-mix(in oklab, var(--kilt-color-foreground) 60%, transparent));
  --kilt-color-shader-ink: light-dark(#c65b3a, #e07a5f);
  --kilt-color-tab-hover-foreground: light-dark(color-mix(in oklch, var(--kilt-color-foreground) 80%, var(--kilt-color-background)), color-mix(in oklch, var(--kilt-color-foreground) 82%, var(--kilt-color-background)));
  --kilt-color-tab-inactive-foreground: light-dark(color-mix(in oklch, var(--kilt-color-foreground) 68%, var(--kilt-color-background)), color-mix(in oklch, var(--kilt-color-foreground) 66%, var(--kilt-color-background)));
  --kilt-color-text-link: light-dark(color-mix(in oklch, var(--kilt-color-primary) 81%, black), var(--kilt-color-primary-ink));
  --kilt-color-warning-subtle: light-dark(color-mix(in oklch, var(--kilt-color-warning) 10%, transparent), color-mix(in oklch, var(--kilt-color-warning) 11%, transparent));
}

